// Simulate reading from a live Twitter feed
const tweets = [
  "Huge flames seen at the Downtown warehouse! Looks like a 3-alarm fire. #fire #emergency",
  "Terrible multi-car crash at Route 66. At least 3 people look badly injured. Send ambulances! #accident",
  "Someone collapsed on the sidewalk in North Hills, they aren't breathing! Need a medic ASAP.",
  "Just got the best coffee in Southside. What a beautiful day!",
  "Brush fire spreading fast near Industrial District due to the high winds. @FireDept",
  "Traffic is terrible around Main Street today. Ugh.",
  "Building collapse in Westside due to the fire. Paramedics and Firefighters needed immediately."
];

const randomTweet = tweets[Math.floor(Math.random() * tweets.length)];

return [
  {
    json: {
      tweet_text: randomTweet,
      timestamp: new Date().toISOString(),
      source: "Mock Twitter Feed"
    }
  }
];
